rows=json.loads((ROOT/"results/hotpotqa_curve50k_threeway_20261005/selected_rows.json").read_text())
per=json.loads((W/"per_question_scores.json").read_text());lookup={(x["method"],x["index"]):x for x in per}
allrows=[]
for i,row in enumerate(rows):
 allrows.append(dict(index=i,id=row["_id"],question=row["input"],references=row["answers"],context_source="/root/adablock/results/hotpotqa_curve50k_threeway_20261005/selected_rows.json",context_row_index=i,predictions={m:lookup[m,i] for m in ["learned","cobs","quest","full","old"]}))
